<?php
namespace ProjectPress\API;use ProjectPress\Includes\Project\Core\ProjectPermissions;use ProjectPress\Includes\Project\ProjectManager;use ProjectPress\Includes\Project\Reports\ProjectReportService;use WP_Error;use WP_REST_Request;use WP_REST_Response;use WP_REST_Server;if(!defined('ABSPATH')){exit;}final class ReportingRoutes{public static function register_routes():void{register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/report',array('methods'=>WP_REST_Server::READABLE,'callback'=>array(self::class,'report'),'permission_callback'=>array(self::class,'can_read')));}public static function report(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$data=(new ProjectReportService(ProjectManager::get_instance()->repository(),new ProjectPermissions()))->for_project($project->get_id());return null===$data?new WP_Error('projectpress_report_unavailable',__('Project report is unavailable.','projectpress'),array('status'=>404)):new WP_REST_Response(array('success'=>true,'data'=>$data),200);}public static function can_read(WP_REST_Request$r){$project=self::project($r);return is_wp_error($project)?$project:((new ProjectPermissions())->can_view($project)?true:new WP_Error('projectpress_rest_forbidden',__('You do not have permission to perform this action.','projectpress'),array('status'=>rest_authorization_required_code())));}private static function project(WP_REST_Request$r){$project=ProjectManager::get_instance()->resolve(sanitize_text_field((string)$r->get_param('project')));return is_wp_error($project)?new WP_Error('projectpress_rest_project_not_found',__('Project not found.','projectpress'),array('status'=>404)):$project;}}
